#!/usr/bin/env bash
# Copy the cpp-linter-js version from bindings/node/Cargo.toml into
# bindings/node/package.json and the version checks in bindings/node/index.js.
# release-plz only updates Cargo manifests, so the release PR needs this step.
set -euo pipefail
cd "$(dirname "$0")/.."

new=$(cargo metadata --format-version 1 --no-deps \
    | jq -r '.packages[] | select(.name == "cpp-linter-js") | .version')
cd bindings/node
old=$(node -p "require('./package.json').version")
if [[ "$old" == "$new" ]]; then
    echo "package.json already has version $new"
    exit 0
fi
npm pkg set version="$new"
# index.js is generated by `napi build`; only its version checks change.
sed -i "s/${old//./\\.}/${new}/g" index.js
echo "Synced bindings/node from $old to $new"
